'use client';

import { useRef } from 'react';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { MenuIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { BRAND, type Attachment } from './data';
import { GlyphField } from './glyph-field';
import { PromptBox } from './prompt-box';
import { RecentRuns } from './recent-runs';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  RUN_MS,
  SCRIPT,
  sentRunIdOf,
  START_MS,
  type Decision,
} from './session';
import { SessionSidebar } from './session-sidebar';
import { Suggestions } from './suggestions';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The width of the `@3xl` container variant: under it the recent sessions live in a sheet. */
const SHEET_BELOW_REM = 48;

/**
 * Nothing calls a network. A real agent plugs in here: the prompt a person starts a session with,
 * and their answer to a run that waits on them.
 */
export type Application13Props = {
  onSend?: (text: string) => void;
  onApprove?: () => void;
  onDeny?: () => void;
};

export default function Application13({
  onSend,
  onApprove,
  onDeny,
}: Application13Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const fieldHostRef = useRef<HTMLElement>(null);
  const isNarrow = useIsNarrow(ref, SHEET_BELOW_REM);
  const isSidebarShown = isNarrow && state.isSidebarOpen;
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.spoken);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function focusPromptAtEnd() {
    requestAnimationFrame(() => {
      const field = ref.current?.querySelector<HTMLTextAreaElement>(
        '[data-prompt-field]'
      );
      if (!field) {
        return;
      }
      const end = field.value.length;
      field.focus();
      field.setSelectionRange(end, end);
    });
  }

  /** The run of a sent prompt starts, then ends: a backend would send these two events itself. */
  function send() {
    const text = state.draft.trim();
    act({ type: 'sent' });
    if (text === '') {
      return;
    }
    const sentCount = state.sentCount + 1;
    const id = sentRunIdOf(sentCount);
    const endsAfter = START_MS + RUN_MS;
    schedule(() => act({ type: 'runStarted', id }), START_MS);
    schedule(() => act({ type: 'runFinished', id }), endsAfter);
    onSend?.(text);
  }

  function closeSidebar() {
    act({ type: 'sidebar', isOpen: false });
    focusLater('[data-sidebar-open]');
  }

  function openSidebar() {
    act({ type: 'sidebar', isOpen: true });
    focusLater('[data-sheet-close="sessions"]');
  }

  function fillPrompt(prompt: string) {
    act({ type: 'picked', prompt });
    if (isSidebarShown) {
      act({ type: 'sidebar', isOpen: false });
    }
    focusPromptAtEnd();
  }

  function startNewSession() {
    fillPrompt('');
  }

  /** The two buttons leave the row, so the focus goes to the row, which now says what was decided. */
  function decide(id: string, decision: Decision) {
    act({ type: 'decided', id, decision });
    focusLater(`[data-run="${id}"]`);
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    schedule(() => act({ type: 'runStarted', id }), START_MS);
    onApprove?.();
  }

  const sidebar = {
    sessions: state.sessions,
    onNewSession: startNewSession,
    onAskAgain: fillPrompt,
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-sidebar text-foreground @container min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] overflow-hidden'>
          <div inert={isSidebarShown} className='flex min-w-0 flex-1 @3xl:p-2'>
            <aside
              aria-label='Sessions'
              className='hidden w-60 shrink-0 pe-2 @3xl:flex'
            >
              {!isNarrow && <SessionSidebar {...sidebar} />}
            </aside>
            <main
              ref={fieldHostRef}
              className='bg-background @3xl:hairline-ring @3xl:ring-border relative flex min-w-0 flex-1 flex-col overflow-hidden @3xl:rounded-xl @3xl:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
            >
              <GlyphField
                hostRef={fieldHostRef}
                isActive={isInView}
                demoLens={state.demoLens}
                demoRipples={state.demoRipples}
              />
              <div className='relative flex min-h-0 flex-1 flex-col overflow-y-auto'>
                <div className='flex h-12 shrink-0 items-center gap-2 px-3'>
                  <Button
                    type='button'
                    variant='ghost'
                    size='icon-sm'
                    data-sidebar-open
                    aria-label='Open the recent sessions'
                    aria-haspopup='dialog'
                    onClick={openSidebar}
                    className='text-muted-foreground @3xl:hidden'
                  >
                    <MenuIcon />
                  </Button>
                  <span className='text-[13px] font-semibold @3xl:hidden'>
                    {BRAND.name}
                  </span>
                  <span className='ms-auto'>
                    <ReplayButton
                      isShown={canReplay}
                      onReplay={restart}
                      label='Replay'
                    />
                  </span>
                </div>
                <div className='mx-auto flex w-full max-w-2xl flex-col gap-8 px-4 pt-4 pb-10 @3xl:pt-8'>
                  <header className='flex flex-col gap-1.5'>
                    <h1 className='text-xl font-semibold text-balance @md:text-2xl'>
                      Start a session
                    </h1>
                    <p className='text-muted-foreground text-sm text-balance'>
                      Say what you need, attach what it takes and choose how far
                      the agent may go on its own
                    </p>
                  </header>
                  <div className='flex flex-col gap-3'>
                    <PromptBox
                      draft={state.draft}
                      attachments={state.attachments}
                      model={state.model}
                      mode={state.mode}
                      hint={state.hint}
                      refusals={state.refusals}
                      pressed={pressed}
                      onType={(text) => act({ type: 'typed', text })}
                      onSend={send}
                      onAttach={(attachments: Attachment[]) =>
                        act({ type: 'attached', attachments })
                      }
                      onDetach={(id) => act({ type: 'detached', id })}
                      onModelChange={(model) =>
                        act({ type: 'modelSet', model })
                      }
                      onModeChange={(mode) => act({ type: 'modeSet', mode })}
                    />
                    <Suggestions
                      draft={state.draft}
                      pressed={pressed}
                      onPick={fillPrompt}
                    />
                  </div>
                  <RecentRuns
                    runs={state.runs}
                    pressed={pressed}
                    onDecide={decide}
                  />
                </div>
              </div>
            </main>
          </div>

          <InlineSheet
            name='sessions'
            label='Recent sessions'
            closeLabel='Close the recent sessions'
            side='start'
            isOpen={isSidebarShown}
            className='@3xl:hidden'
            panelClassName='bg-sidebar gap-1 p-3'
            onClose={closeSidebar}
          >
            {isNarrow && <SessionSidebar {...sidebar} />}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { HistoryIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import { BRAND, DAYS, type PastSession } from './data';

/** The ring is drawn inside the row: the row sits in a box that clips while it arrives. */
const ROW =
  'hover:bg-foreground/5 focus-visible:ring-ring/25 flex h-7 w-full min-w-0 cursor-pointer items-center gap-2 rounded-md px-2 text-start text-[13px] font-medium outline-none transition-colors duration-150 focus-visible:ring-[3px] focus-visible:ring-inset';

type SessionRowProps = {
  session: PastSession;
  onAskAgain: (prompt: string) => void;
};

function SessionRow({ session, onAskAgain }: SessionRowProps) {
  function askAgain() {
    onAskAgain(session.prompt);
  }

  return (
    <button
      type='button'
      aria-label={`Ask again: ${session.title}`}
      onClick={askAgain}
      className={ROW}
    >
      <HistoryIcon className='text-muted-foreground size-4 shrink-0' />
      <span className='min-w-0 flex-1 truncate'>{session.title}</span>
    </button>
  );
}

type SessionSidebarProps = {
  sessions: PastSession[];
  onNewSession: () => void;
  onAskAgain: (prompt: string) => void;
};

/** A past session puts its prompt back in the field, ready to be sent again or changed first. */
export function SessionSidebar({
  sessions,
  onNewSession,
  onAskAgain,
}: SessionSidebarProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);

  return (
    <div className='flex min-h-0 w-full flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <div className='flex h-9 items-center gap-2 px-1.5'>
          <CompanyMark seed={BRAND.name} className='size-6 rounded-md' />
          <span className='text-[13px] font-semibold'>{BRAND.name}</span>
        </div>
        <Button
          type='button'
          variant='outline'
          onClick={onNewSession}
          className='w-full justify-start'
        >
          <PlusIcon />
          New session
        </Button>
      </div>
      <nav
        aria-label='Recent sessions'
        className='-mx-1 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-1'
      >
        {DAYS.map((day) => {
          const ofDay = sessions.filter((session) => session.day === day);
          return (
            <section key={day} className='flex flex-col gap-0.5'>
              <h2 className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
                {day}
              </h2>
              <ul className='flex flex-col'>
                <AnimatePresence initial={false}>
                  {ofDay.map((session) => (
                    <motion.li
                      key={session.id}
                      className='-mx-1 overflow-hidden px-1'
                      {...rowPresence}
                    >
                      <SessionRow session={session} onAskAgain={onAskAgain} />
                    </motion.li>
                  ))}
                </AnimatePresence>
              </ul>
            </section>
          );
        })}
      </nav>
    </div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useId, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import {
  ArrowUpIcon,
  FileTextIcon,
  PaperclipIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

import {
  EMPTY_PROMPT_HINT,
  FULL_HINT,
  type Attachment,
  type ModeId,
  type ModelId,
} from './data';
import { ModeKey, ModelKey } from './prompt-keys';
import type { Hint } from './session';

const KILOBYTE = 1024;

const MEGABYTE = KILOBYTE * KILOBYTE;

const HINT_TEXT: Record<Hint, string> = {
  none: '',
  empty: EMPTY_PROMPT_HINT,
  full: FULL_HINT,
};

const NUDGE = { x: [0, -4, 4, 0] };

const STILL = { x: 0 };

/** A refused entry nudges its reason once. Reduced motion keeps it still. */
function nudgeOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return NUDGE;
}

/** 48 KB, 1.2 MB. */
function formatBytes(bytes: number) {
  if (bytes < MEGABYTE) {
    const rounded = Math.round(bytes / KILOBYTE);
    const kilobytes = Math.max(1, rounded);
    return `${kilobytes} KB`;
  }
  const megabytes = bytes / MEGABYTE;
  return `${megabytes.toFixed(1)} MB`;
}

function describedByOf(hasHint: boolean, hintId: string) {
  if (hasHint) {
    return hintId;
  }
  return undefined;
}

function isSendKey(event: React.KeyboardEvent<HTMLTextAreaElement>) {
  const isPlainEnter = event.key === 'Enter' && !event.shiftKey;
  return isPlainEnter && !event.nativeEvent.isComposing;
}

type AttachmentChipProps = {
  attachment: Attachment;
  onRemove: (id: string) => void;
};

function AttachmentChip({ attachment, onRemove }: AttachmentChipProps) {
  function remove() {
    onRemove(attachment.id);
  }

  return (
    <li className='bg-foreground/[0.05] flex h-7 max-w-full items-center gap-1.5 rounded-lg ps-2 pe-1 text-xs transition-[opacity,scale] duration-200 ease-(--ease-out-strong) starting:scale-95 starting:opacity-0'>
      <FileTextIcon className='text-muted-foreground size-3.5 shrink-0' />
      <span className='min-w-0 truncate'>{attachment.name}</span>
      <span className='text-muted-foreground shrink-0 tabular-nums'>
        {formatBytes(attachment.bytes)}
      </span>
      <button
        type='button'
        aria-label={`Remove ${attachment.name}`}
        onClick={remove}
        className='text-muted-foreground hover:bg-foreground/[0.07] hover:text-foreground focus-visible:ring-ring/25 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px] active:scale-[0.97]'
      >
        <XIcon className='size-3' />
      </button>
    </li>
  );
}

type PromptBoxProps = {
  draft: string;
  attachments: Attachment[];
  model: ModelId;
  mode: ModeId;
  hint: Hint;
  refusals: number;
  pressed: string | null;
  onType: (text: string) => void;
  onSend: () => void;
  onAttach: (attachments: Attachment[]) => void;
  onDetach: (id: string) => void;
  onModelChange: (model: ModelId) => void;
  onModeChange: (mode: ModeId) => void;
};

/** Nothing is uploaded here: a picked file is only listed, by its name and its size. */
export function PromptBox({
  draft,
  attachments,
  model,
  mode,
  hint,
  refusals,
  pressed,
  onType,
  onSend,
  onAttach,
  onDetach,
  onModelChange,
  onModeChange,
}: PromptBoxProps) {
  const hintId = useId();
  const pickerRef = useRef<HTMLInputElement>(null);
  const pickedCount = useRef(0);
  const shouldReduceMotion = usePrefersReducedMotion();
  const hasHint = hint !== 'none';
  const hasAttachments = attachments.length > 0;

  function sendFromKeys(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (!isSendKey(event)) {
      return;
    }
    event.preventDefault();
    onSend();
  }

  function openPicker() {
    pickerRef.current?.click();
  }

  function attachmentOf(file: File): Attachment {
    pickedCount.current += 1;
    const id = `picked-${pickedCount.current}`;
    return { id, name: file.name, bytes: file.size };
  }

  function attachPicked(event: React.ChangeEvent<HTMLInputElement>) {
    const picked = event.target.files ?? [];
    const files = Array.from(picked);
    event.target.value = '';
    if (files.length === 0) {
      return;
    }
    const added = files.map(attachmentOf);
    onAttach(added);
  }

  return (
    <div
      data-solid
      className='bg-card hairline-ring ring-foreground/12 has-[textarea:focus-visible]:ring-ring/25 dark:bg-foreground/[0.04] dark:ring-foreground/15 relative flex flex-col rounded-2xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-[box-shadow] duration-150 has-[textarea:focus-visible]:ring-[3px]'
    >
      <AnimatedSize>
        {hasAttachments && (
          <ul
            aria-label='Attached files'
            className='flex flex-wrap gap-1.5 pb-2'
          >
            {attachments.map((attachment) => (
              <AttachmentChip
                key={attachment.id}
                attachment={attachment}
                onRemove={onDetach}
              />
            ))}
          </ul>
        )}
      </AnimatedSize>
      <textarea
        data-prompt-field
        value={draft}
        rows={2}
        aria-label='What the agent should do'
        aria-invalid={hasHint}
        aria-describedby={describedByOf(hasHint, hintId)}
        placeholder='Describe a task, or pick one under this field'
        onChange={(event) => onType(event.target.value)}
        onKeyDown={sendFromKeys}
        className='placeholder:text-muted-foreground/75 field-sizing-content max-h-[8lh] min-h-[2lh] resize-none bg-transparent px-1.5 py-1 text-base leading-normal outline-none md:text-sm'
      />
      <div className='flex flex-wrap items-center gap-1.5 pt-2'>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Attach files'
          onClick={openPicker}
          className={cn(
            'text-muted-foreground',
            pressedQuietOf(pressed === 'attach')
          )}
        >
          <PaperclipIcon />
        </Button>
        <input
          ref={pickerRef}
          type='file'
          multiple
          tabIndex={-1}
          aria-hidden='true'
          onChange={attachPicked}
          className='sr-only'
        />
        <ModelKey value={model} onValueChange={onModelChange} />
        <ModeKey value={mode} onValueChange={onModeChange} />
        <Button
          type='button'
          size='sm'
          onClick={onSend}
          className={cn('ms-auto', pressedSolidOf(pressed === 'send'))}
        >
          Start
          <ArrowUpIcon />
        </Button>
      </div>
      {hasHint && (
        <motion.p
          key={refusals}
          id={hintId}
          animate={nudgeOf(shouldReduceMotion)}
          transition={{ duration: 0.28 }}
          className='text-destructive-ink px-1.5 pt-2 text-xs'
        >
          {HINT_TEXT[hint]}
        </motion.p>
      )}
    </div>
  );
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import {
  ChevronDownIcon,
  HandIcon,
  ListChecksIcon,
  ZapIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import {
  modelOf,
  MODELS,
  modeOf,
  MODES,
  type ModeId,
  type ModelId,
} from './data';

/** Both controls are drawn as key caps, the material of a key. */
const KEY = 'keycap-3d text-foreground h-7 gap-1.5 rounded-md px-2 text-xs';

const MODEL_NAMES = MODELS.map((model) => model.name);

const MODE_LABELS = MODES.map((mode) => mode.label);

const MODE_ICON: Record<ModeId, Icon> = {
  ask: HandIcon,
  plan: ListChecksIcon,
  act: ZapIcon,
};

type ModelKeyProps = {
  value: ModelId;
  onValueChange: (model: ModelId) => void;
};

/** The menu belongs to a person. The demonstration changes the value, and the key rolls to its new name. */
export function ModelKey({ value, onValueChange }: ModelKeyProps) {
  const model = modelOf(value);

  function change(next: unknown) {
    const found = MODELS.find((candidate) => candidate.id === next);
    if (found) {
      onValueChange(found.id);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-label={`Model: ${model.name}`}
            className={KEY}
          />
        }
      >
        <Swap swapKey={model.brand}>
          <BrandTile brand={model.brand} size='sm' />
        </Swap>
        <WordRoll text={model.name} labels={MODEL_NAMES} />
        <ChevronDownIcon className='size-3.5 opacity-60' />
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' align='start' className='w-56'>
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>Model</DropdownMenuGroupLabel>
          <DropdownMenuRadioGroup value={value} onValueChange={change}>
            {MODELS.map((option) => (
              <DropdownMenuRadioItem
                key={option.id}
                value={option.id}
                closeOnClick
              >
                <BrandTile brand={option.brand} size='sm' />
                {option.name}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

type ModeKeyProps = {
  value: ModeId;
  onValueChange: (mode: ModeId) => void;
};

export function ModeKey({ value, onValueChange }: ModeKeyProps) {
  const mode = modeOf(value);
  const ModeIcon = MODE_ICON[value];

  function change(next: unknown) {
    const found = MODES.find((candidate) => candidate.id === next);
    if (found) {
      onValueChange(found.id);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-label={`Mode: ${mode.label}`}
            className={KEY}
          />
        }
      >
        <Swap swapKey={value}>
          <ModeIcon className='size-3.5' />
        </Swap>
        <WordRoll text={mode.label} labels={MODE_LABELS} />
        <ChevronDownIcon className='size-3.5 opacity-60' />
      </DropdownMenuTrigger>
      <DropdownMenuContent side='top' align='start' className='w-72'>
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>How the agent works</DropdownMenuGroupLabel>
          <DropdownMenuRadioGroup value={value} onValueChange={change}>
            {MODES.map((option) => {
              const OptionIcon = MODE_ICON[option.id];
              return (
                <DropdownMenuRadioItem
                  key={option.id}
                  value={option.id}
                  closeOnClick
                  className='h-auto items-start py-1.5'
                >
                  <OptionIcon className='mt-0.5' />
                  <span className='flex min-w-0 flex-col'>
                    <span>{option.label}</span>
                    <span className='text-muted-foreground text-xs'>
                      {option.hint}
                    </span>
                  </span>
                </DropdownMenuRadioItem>
              );
            })}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  CodeIcon,
  PencilIcon,
  SearchIcon,
  TableIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';

import { SUGGESTIONS, type Suggestion, type SuggestionKind } from './data';

const KIND_ICON: Record<SuggestionKind, Icon> = {
  data: TableIcon,
  writing: PencilIcon,
  search: SearchIcon,
  code: CodeIcon,
};

/** The card whose task sits in the prompt keeps a ring, so the pick stays visible after the press. */
function pickedOf(isPicked: boolean) {
  if (isPicked) {
    return 'ring-primary/45';
