'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { useNow } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  elapsedOf,
  formatCost,
  formatDuration,
  seriesColorOf,
} from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { AGENTS, type RunStatus } from './data';
import type { Decision, Run } from './session';

const STATUS_WORD: Record<RunStatus, string> = {
  queued: 'Queued',
  running: 'Running',
  waiting: 'Waiting on you',
  done: 'Done',
  failed: 'Failed',
};

const STATUS_WORDS = Object.values(STATUS_WORD);

const DOT_TONE: Record<RunStatus, string> = {
  queued: 'bg-muted-foreground/45',
  running: 'bg-info',
  waiting: 'bg-warning',
  done: 'bg-success',
  failed: 'bg-destructive',
};

const WORD_TONE: Record<RunStatus, string> = {
  queued: 'text-muted-foreground',
  running: 'text-foreground',
  waiting: 'text-warning-foreground',
  done: 'text-muted-foreground',
  failed: 'text-destructive-ink',
};

/** Only a run that is really running breathes. */
function pulseOf(status: RunStatus) {
  if (status === 'running') {
    return 'animate-pulse';
  }
  return undefined;
}

const SECOND_MS = 1000;

/** A run on the start screen has been going for minutes: its clock ticks once a second, and only this text re-renders. */
function RunningClock({ run }: { run: Run }) {
  const now = useNow(SECOND_MS, true);
  const elapsed = elapsedOf(run, now);

  return <span className='w-14 tabular-nums'>{formatDuration(elapsed)}</span>;
}

function RunClock({ run }: { run: Run }) {
  if (run.status === 'queued') {
    return null;
  }
  if (run.status === 'running') {
    return <RunningClock run={run} />;
  }
  const end = run.endedAt ?? run.startedAt;
  const elapsed = elapsedOf(run, end);
  return <span className='tabular-nums'>{formatDuration(elapsed)}</span>;
}

/** A run that waits shows its request and its two answers. Any other run shows the trace it kept, if it has one. */
function traceOf(run: Run) {
  if (run.status === 'waiting') {
    return undefined;
  }
  return run.note;
}

type RunRowProps = {
  run: Run;
  isAllowPressed: boolean;
  onDecide: (id: string, decision: Decision) => void;
};

function RunRow({ run, isAllowPressed, onDecide }: RunRowProps) {
  const agent = AGENTS[run.agentId];
  const isWaiting = run.status === 'waiting';
  const hasCost = run.costUsd > 0;
  const trace = traceOf(run);

  function allow() {
    onDecide(run.id, 'approved');
  }

  function deny() {
    onDecide(run.id, 'denied');
  }

  return (
    <div
      data-run={run.id}
      tabIndex={-1}
      className='flex items-start gap-3 px-3 py-2.5 outline-none'
    >
      <MeshTile
        seed={agent.name}
        color={seriesColorOf(agent.series)}
        size='lg'
      />
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='flex items-baseline gap-3'>
          <span className='min-w-0 flex-1 truncate text-[13px] font-medium'>
            {run.title}
          </span>
          {hasCost && (
            <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
              {formatCost(run.costUsd)}
            </span>
          )}
        </p>
        <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-0.5 text-xs'>
          <span>{agent.name}</span>
          <span
            className={cn(
              'flex items-center gap-1.5 transition-colors duration-200',
              WORD_TONE[run.status]
            )}
          >
            <span
              aria-hidden='true'
              className={cn(
                'size-1.5 shrink-0 rounded-full transition-colors duration-200',
                DOT_TONE[run.status],
                pulseOf(run.status)
              )}
            />
            <WordRoll text={STATUS_WORD[run.status]} labels={STATUS_WORDS} />
          </span>
          <RunClock run={run} />
        </p>
        {isWaiting && (
          <div className='flex flex-wrap items-center gap-2 pt-1.5'>
            <span className='text-foreground/85 min-w-0 flex-1 text-xs'>
              {run.request}
            </span>
            <Button
              type='button'
              size='sm'
              aria-label={`Allow: ${run.request}`}
              onClick={allow}
              className={pressedSolidOf(isAllowPressed)}
            >
              Allow
            </Button>
            <Button
              type='button'
              size='sm'
              variant='outline'
              aria-label={`Deny: ${run.request}`}
              onClick={deny}
            >
              Deny
            </Button>
          </div>
        )}
        {trace && (
          <p
            key={trace}
            className='text-muted-foreground text-xs transition-opacity duration-300 starting:opacity-0'
          >
            {trace}
          </p>
        )}
      </div>
    </div>
  );
}

type RecentRunsProps = {
  runs: Run[];
  pressed: string | null;
  onDecide: (id: string, decision: Decision) => void;
};

/** A new run arrives at the top with its height and the oldest one leaves, so the list keeps its length. */
export function RecentRuns({ runs, pressed, onDecide }: RecentRunsProps) {
  const titleId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);

  return (
    <section aria-labelledby={titleId} className='flex flex-col gap-2'>
      <div className='flex items-center gap-2 px-1'>
        <h2 id={titleId} className='text-[13px] font-medium'>
          Recent runs
        </h2>
        <Badge variant='secondary'>Illustrative</Badge>
      </div>
      <ul
        data-solid
        className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] flex flex-col rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
      >
        <AnimatePresence initial={false}>
          {runs.map((run) => (
            <motion.li
              key={run.id}
              className='overflow-hidden'
              {...rowPresence}
            >
              <RunRow
                run={run}
                isAllowPressed={pressed === 'allow'}
                onDecide={onDecide}
              />
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </section>
  );
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { createGlyphField, type GlyphFieldEngine } from './glyph-engine';
import type { Point } from './session';

type GlyphFieldProps = {
  hostRef: RefObject<HTMLElement | null>;
  isActive: boolean;
  demoLens: Point | null;
  demoRipples: number;
};

/**
 * The field of glyphs behind the content of `hostRef`. It takes its colour and its mono face from
 * the classes of the canvas, draws only while it is in view, and holds one still frame under
 * reduced motion. It is decoration: nothing in it is read aloud.
 */
export function GlyphField({
  hostRef,
  isActive,
  demoLens,
  demoRipples,
}: GlyphFieldProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<GlyphFieldEngine | null>(null);
  const seenRipples = useRef(demoRipples);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isLive = isActive && !shouldReduceMotion;

  useEffect(() => {
    const canvas = canvasRef.current;
    const host = hostRef.current;
    if (!canvas || !host) {
      return;
    }
    const engine = createGlyphField(canvas, host);
    engineRef.current = engine;
    return () => {
      engine?.dispose();
      engineRef.current = null;
    };
  }, [hostRef]);

  useEffect(() => {
    engineRef.current?.setLive(isLive);
  }, [isLive]);

  useEffect(() => {
    engineRef.current?.aimDemo(demoLens);
  }, [demoLens]);

  useEffect(() => {
    const hasNewRipple = demoRipples > seenRipples.current;
    seenRipples.current = demoRipples;
    if (hasNewRipple) {
      engineRef.current?.rippleDemo();
    }
  }, [demoRipples]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden='true'
      className='text-muted-foreground pointer-events-none absolute inset-0 size-full font-mono'
    />
  );
}

import {
  inkGlyphs,
  measure,
  paint,
  REST_ALPHA,
  RIPPLE_MS,
  type Lens,
  type Ripple,
  type Surface,
} from './glyph-paint';
import type { Point } from './session';

const POINTER_EASE_S = 0.12;

const DEMO_EASE_S = 0.38;

const FADE_EASE_S = 0.25;

/** A frame that comes late, after a hidden tab, moves the lens no further than this long would. */
const MAX_STEP_S = 0.05;

const REST_PX = 0.4;

/** A press on one of these is a press on the interface, not on the empty field behind it. */
const SOLID = '[data-solid], button, a, input, textarea, select, label';

type FieldState = Surface & {
  lens: Lens;
  target: Lens;
  easeSeconds: number;
  demo: Point | null;
  hasPointer: boolean;
  isLive: boolean;
  ripples: Ripple[];
  frame: number;
  lastTick: number;
};

export type GlyphFieldEngine = {
  aimDemo: (point: Point | null) => void;
  rippleDemo: () => void;
  setLive: (isLive: boolean) => void;
  dispose: () => void;
};

function draw(state: FieldState) {
  const now = performance.now();
  paint(state, state.lens, state.ripples, now);
}

/** The still frame: the lens where it is aimed, no ripple. It is what shows at rest and under reduced motion. */
function settle(state: FieldState) {
  state.lens.x = state.target.x;
  state.lens.y = state.target.y;
  state.lens.alpha = state.target.alpha;
  state.ripples = [];
  draw(state);
}

function isAtRest(state: FieldState) {
  const { lens, target } = state;
  const offsetX = target.x - lens.x;
  const offsetY = target.y - lens.y;
  const distance = Math.hypot(offsetX, offsetY);
  const alphaGap = Math.abs(target.alpha - lens.alpha);
  const isStill = distance < REST_PX;
  const isFaded = alphaGap < REST_ALPHA;
  const isSettled = isStill && isFaded;
  return isSettled && state.ripples.length === 0;
}

/** How much of the way left is covered in `seconds`: the same glide whatever the frame rate. */
function shareOf(seconds: number, easeSeconds: number) {
  const ratio = seconds / easeSeconds;
  const decay = Math.exp(-ratio);
  return 1 - decay;
}

function towards(from: number, to: number, share: number) {
  const gap = to - from;
  const step = gap * share;
  return from + step;
}

function glide(state: FieldState, seconds: number) {
  const { lens, target } = state;
  const move = shareOf(seconds, state.easeSeconds);
  const fade = shareOf(seconds, FADE_EASE_S);
  lens.x = towards(lens.x, target.x, move);
  lens.y = towards(lens.y, target.y, move);
  lens.alpha = towards(lens.alpha, target.alpha, fade);
}

function isAlive(ripple: Ripple, now: number) {
  const age = now - ripple.startedAt;
  return age < RIPPLE_MS;
}

/** Frames are asked for only while something moves. Once the lens has arrived and no ripple is left, the loop ends. */
function tick(state: FieldState, now: number) {
  const sinceLast = now - state.lastTick;
  const elapsed = sinceLast / 1000;
  const seconds = Math.min(MAX_STEP_S, elapsed);
  state.lastTick = now;
  glide(state, seconds);
  state.ripples = state.ripples.filter((ripple) => isAlive(ripple, now));
  if (isAtRest(state)) {
    state.frame = 0;
    settle(state);
    return;
  }
  paint(state, state.lens, state.ripples, now);
  state.frame = requestAnimationFrame((next) => tick(state, next));
}

function wake(state: FieldState) {
  const isAsleep = state.frame === 0;
  if (!state.isLive || !isAsleep) {
    return;
  }
  state.lastTick = performance.now();
  state.frame = requestAnimationFrame((now) => tick(state, now));
}

/** A lens that was away fades in where it is aimed: it does not glide in from where it left. */
function aimAt(state: FieldState, x: number, y: number, easeSeconds: number) {
  const wasAway = state.lens.alpha <= REST_ALPHA;
  state.target.x = x;
  state.target.y = y;
  state.target.alpha = 1;
  state.easeSeconds = easeSeconds;
  if (wasAway) {
    state.lens.x = x;
    state.lens.y = y;
  }
}

/** Without a pointer on the field the lens goes where the demonstration holds it, or away. */
function aimAtDemo(state: FieldState) {
  const { demo } = state;
  if (!demo) {
    state.target.alpha = 0;
    return;
  }
  const x = demo.x * state.width;
  const y = demo.y * state.height;
  aimAt(state, x, y, DEMO_EASE_S);
}

function placeOf(state: FieldState, event: PointerEvent) {
  const box = state.canvas.getBoundingClientRect();
  const x = event.clientX - box.left;
  const y = event.clientY - box.top;
  return { x, y };
}

function isOnEmptySpace(event: PointerEvent) {
  const target = event.target;
  if (!(target instanceof Element)) {
    return false;
  }
  return target.closest(SOLID) === null;
}

function followPointer(state: FieldState, event: PointerEvent) {
  if (!state.isLive) {
    return;
  }
  const place = placeOf(state, event);
  state.hasPointer = true;
  aimAt(state, place.x, place.y, POINTER_EASE_S);
  wake(state);
}

function releasePointer(state: FieldState) {
  state.hasPointer = false;
  if (!state.isLive) {
    return;
  }
  aimAtDemo(state);
  wake(state);
}

function startRipple(state: FieldState, x: number, y: number) {
  const startedAt = performance.now();
  state.ripples.push({ x, y, startedAt });
  wake(state);
}

function pressField(state: FieldState, event: PointerEvent) {
  if (!state.isLive) {
    return;
  }
  followPointer(state, event);
  if (!isOnEmptySpace(event)) {
    return;
  }
  const place = placeOf(state, event);
  startRipple(state, place.x, place.y);
}

/** A new theme: the glyphs take the new colour and the frame is drawn again as it stands. */
function reink(state: FieldState) {
  inkGlyphs(state);
  draw(state);
}

/** A new size: the field is measured again and drawn where it stands, without a glide. */
function refit(state: FieldState) {
  measure(state);
  if (!state.hasPointer) {
    aimAtDemo(state);
  }
  settle(state);
}

function setLive(state: FieldState, isLive: boolean) {
  state.isLive = isLive;
  if (isLive) {
    wake(state);
    return;
  }
  cancelAnimationFrame(state.frame);
  state.frame = 0;
  settle(state);
}

function aimDemo(state: FieldState, point: Point | null) {
  state.demo = point;
  if (state.hasPointer) {
    return;
  }
  aimAtDemo(state);
  if (!state.isLive) {
    settle(state);
    return;
  }
  wake(state);
}

function rippleDemo(state: FieldState) {
  if (!state.isLive) {
    return;
  }
  startRipple(state, state.target.x, state.target.y);
}

/**
 * One canvas behind the content of `host`. The lens follows the pointer over `host`, a press on empty
 * space sends a ripple, and nothing is drawn while nothing moves.
 */
export function createGlyphField(
  canvas: HTMLCanvasElement,
  host: HTMLElement
): GlyphFieldEngine | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  const state: FieldState = {
    canvas,
    pen,
    width: 0,
    height: 0,
    pixelRatio: 1,
    sprites: [],
    inked: [],
    lens: { x: 0, y: 0, alpha: 0 },
    target: { x: 0, y: 0, alpha: 0 },
    easeSeconds: DEMO_EASE_S,
    demo: null,
    hasPointer: false,
    isLive: false,
    ripples: [],
    frame: 0,
    lastTick: 0,
  };

  function onMove(event: PointerEvent) {
    followPointer(state, event);
  }

  function onLeave() {
    releasePointer(state);
  }

  function onPress(event: PointerEvent) {
    pressField(state, event);
  }

  function onResize() {
    refit(state);
  }

  function onTheme() {
    reink(state);
  }

  // The glyphs are inked before anything can ask for a frame.
  measure(state);
  const sizeObserver = new ResizeObserver(onResize);
  const themeObserver = new MutationObserver(onTheme);
  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class', 'data-theme'],
  });
  host.addEventListener('pointermove', onMove, { passive: true });
  host.addEventListener('pointerleave', onLeave, { passive: true });
  host.addEventListener('pointerdown', onPress, { passive: true });

  return {
    aimDemo: (point) => aimDemo(state, point),
    rippleDemo: () => rippleDemo(state),
    setLive: (isLive) => setLive(state, isLive),
    dispose() {
      cancelAnimationFrame(state.frame);
      state.frame = 0;
      sizeObserver.disconnect();
      themeObserver.disconnect();
      host.removeEventListener('pointermove', onMove);
      host.removeEventListener('pointerleave', onLeave);
      host.removeEventListener('pointerdown', onPress);
    },
  };
}

const CELL_PX = 22;

const HALF_CELL_PX = CELL_PX / 2;

const GLYPH_PX = 12;

const SPRITE_PX = 16;

const HALF_SPRITE_PX = SPRITE_PX / 2;

const GLYPHS = ['·', '+', '/'];

/** Out of a hundred cells, how many are dots and how many are dots or plus signs. The rest are slashes. */
const DOT_SHARE = 62;

const DOT_OR_PLUS_SHARE = 86;

const LENS_RADIUS_PX = 150;

/** The glyphs stay faint at the heart of the lens: text sits above the field and must stay easy to read. */
const LENS_INK = 0.6;

export const RIPPLE_MS = 1500;

const RIPPLE_SPEED_PX = 560;

const RIPPLE_HALF_BAND_PX = 27;

const RIPPLE_PUSH_PX = 5;

const RIPPLE_INK = 0.55;

/** A backing store above two device pixels a point costs four times the fill for glyphs nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

/** Under this much ink a lens counts as away: it is neither drawn nor waited for. */
export const REST_ALPHA = 0.01;

export type Lens = {
  x: number;
  y: number;
  alpha: number;
};

export type Ripple = {
  x: number;
  y: number;
  startedAt: number;
};

type Cells = {
  first: number;
  last: number;
};

type Patch = {
  x: number;
  y: number;
  side: number;
};

export type Surface = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  width: number;
  height: number;
  pixelRatio: number;
  sprites: HTMLCanvasElement[];
  inked: Patch[];
};

/** The same cell always shows the same glyph, so the field does not shuffle between two frames. */
function glyphIndexOf(column: number, row: number) {
  const columnHash = Math.imul(column, 73856093);
  const rowHash = Math.imul(row, 19349663);
  const mixed = Math.imul(columnHash ^ rowHash, 2654435761);
  const positive = mixed >>> 0;
  const share = positive % 100;
  if (share < DOT_SHARE) {
    return 0;
  }
  if (share < DOT_OR_PLUS_SHARE) {
    return 1;
  }
  return 2;
}

/** Each glyph is drawn as text once, in the colour and the mono face of the canvas, then stamped. */
function spriteOf(
  glyph: string,
  ink: string,
  face: string,
  pixelRatio: number
) {
  const sprite = document.createElement('canvas');
  const side = Math.round(SPRITE_PX * pixelRatio);
  sprite.width = side;
  sprite.height = side;
  const pen = sprite.getContext('2d');
  if (!pen) {
    return sprite;
  }
  const fontSize = GLYPH_PX * pixelRatio;
  const middle = side / 2;
  pen.font = `${fontSize}px ${face}`;
  pen.textAlign = 'center';
  pen.textBaseline = 'middle';
  pen.fillStyle = ink;
  pen.fillText(glyph, middle, middle);
  return sprite;
}

export function inkGlyphs(surface: Surface) {
  const style = getComputedStyle(surface.canvas);
  surface.sprites = GLYPHS.map((glyph) =>
    spriteOf(glyph, style.color, style.fontFamily, surface.pixelRatio)
  );
}

export function measure(surface: Surface) {
  const box = surface.canvas.getBoundingClientRect();
  const devicePixelRatio = window.devicePixelRatio || 1;
  const pixelRatio = Math.min(devicePixelRatio, MAX_PIXEL_RATIO);
  const deviceWidth = box.width * pixelRatio;
  const deviceHeight = box.height * pixelRatio;
  surface.width = box.width;
  surface.height = box.height;
  surface.pixelRatio = pixelRatio;
  surface.canvas.width = Math.round(deviceWidth);
  surface.canvas.height = Math.round(deviceHeight);
  surface.pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  surface.inked = [];
  inkGlyphs(surface);
}

function cellAt(position: number) {
  return Math.floor(position / CELL_PX);
}

function cellsAround(centre: number, reach: number, extent: number): Cells {
  const lowest = cellAt(centre - reach);
  const highest = cellAt(centre + reach);
  const lastCell = cellAt(extent);
  const first = Math.max(0, lowest);
  const last = Math.min(lastCell, highest);
  return { first, last };
}

function centreOf(cell: number) {
  const start = cell * CELL_PX;
  return start + HALF_CELL_PX;
}

function stamp(
  surface: Surface,
  column: number,
  row: number,
  x: number,
  y: number,
  ink: number
) {
  const glyphIndex = glyphIndexOf(column, row);
  const sprite = surface.sprites[glyphIndex];
  if (!sprite) {
    return;
  }
  surface.pen.globalAlpha = ink;
  surface.pen.drawImage(
    sprite,
    x - HALF_SPRITE_PX,
    y - HALF_SPRITE_PX,
    SPRITE_PX,
    SPRITE_PX
  );
}

/** The square a lens or a ring was drawn into, with room for the glyphs that straddle its edge. */
function patchAround(x: number, y: number, reach: number): Patch {
  const margin = reach + SPRITE_PX;
  const left = x - margin;
  const top = y - margin;
  const side = margin * 2;
  return { x: left, y: top, side };
}

/** Only what the last frame inked is wiped, never the whole canvas: a still lens leaves most of it untouched. */
function wipe(surface: Surface) {
  surface.pen.globalAlpha = 1;
  for (const patch of surface.inked) {
    surface.pen.clearRect(patch.x, patch.y, patch.side, patch.side);
  }
  surface.inked = [];
}

/** Only the cells under the lens are drawn: the rest of the field costs nothing. */
function paintLens(surface: Surface, lens: Lens) {
  if (lens.alpha <= REST_ALPHA) {
    return;
  }
  const patch = patchAround(lens.x, lens.y, LENS_RADIUS_PX);
  surface.inked.push(patch);
  const columns = cellsAround(lens.x, LENS_RADIUS_PX, surface.width);
  const rows = cellsAround(lens.y, LENS_RADIUS_PX, surface.height);
  for (let row = rows.first; row <= rows.last; row += 1) {
    for (let column = columns.first; column <= columns.last; column += 1) {
      const x = centreOf(column);
      const y = centreOf(row);
      const offsetX = x - lens.x;
      const offsetY = y - lens.y;
      const distance = Math.hypot(offsetX, offsetY);
      if (distance >= LENS_RADIUS_PX) {
        continue;
      }
      const farness = distance / LENS_RADIUS_PX;
      const closeness = 1 - farness;
      const softness = closeness * closeness;
      const shown = softness * lens.alpha;
      const ink = shown * LENS_INK;
      stamp(surface, column, row, x, y, ink);
    }
  }
}

/** A ring that widens and fades: the glyphs on its crest show and are pushed outwards a little. */
function paintRipple(surface: Surface, ripple: Ripple, now: number) {
  const age = now - ripple.startedAt;
  const spent = age / RIPPLE_MS;
  const life = 1 - spent;
  const seconds = age / 1000;
  const radius = seconds * RIPPLE_SPEED_PX;
  const reach = radius + RIPPLE_HALF_BAND_PX;
  const inkedReach = reach + RIPPLE_PUSH_PX;
  const patch = patchAround(ripple.x, ripple.y, inkedReach);
  surface.inked.push(patch);
  const columns = cellsAround(ripple.x, reach, surface.width);
  const rows = cellsAround(ripple.y, reach, surface.height);
  for (let row = rows.first; row <= rows.last; row += 1) {
    for (let column = columns.first; column <= columns.last; column += 1) {
      const x = centreOf(column);
      const y = centreOf(row);
      const offsetX = x - ripple.x;
      const offsetY = y - ripple.y;
      const distance = Math.hypot(offsetX, offsetY);
      const gap = Math.abs(distance - radius);
      if (gap >= RIPPLE_HALF_BAND_PX) {
        continue;
      }
      const offCrest = gap / RIPPLE_HALF_BAND_PX;
      const crest = 1 - offCrest;
      const strength = crest * life;
      const pushPx = strength * RIPPLE_PUSH_PX;
      const pushShare = pushPx / Math.max(distance, 1);
      const pushX = offsetX * pushShare;
      const pushY = offsetY * pushShare;
      const pushedX = x + pushX;
      const pushedY = y + pushY;
      const ink = strength * RIPPLE_INK;
      stamp(surface, column, row, pushedX, pushedY, ink);
    }
  }
}

export function paint(
  surface: Surface,
  lens: Lens,
  ripples: Ripple[],
  now: number
) {
  wipe(surface);
  paintLens(surface, lens);
  for (const ripple of ripples) {
    paintRipple(surface, ripple, now);
  }
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { restingOf } from '@/registry/ndeko/lib/run-session';
import { wordsOf } from '@/registry/ndeko/lib/words';

import {
  DEMO_ATTACHMENT,
  DEMO_SUGGESTION,
  EMPTY_PROMPT_HINT,
  FULL_HINT,
  MAX_ATTACHMENTS,
  RUNS,
  RUNS_SHOWN,
  SESSIONS,
  STARTING_AGENT,
  TITLE_WORDS,
  WAITING_RUN,
  type AgentId,
  type Attachment,
  type ModeId,
  type ModelId,
  type PastSession,
  type RunSeed,
  type RunStatus,
} from './data';

/** A place in the field of glyphs, as a share of its width and of its height. */
export type Point = {
  x: number;
  y: number;
};

export type Decision = 'approved' | 'denied';

export type Hint = 'none' | 'empty' | 'full';

export type Run = {
  id: string;
  agentId: AgentId;
  title: string;
  status: RunStatus;
  startedAt: number;
  endedAt?: number;
  costUsd: number;
  request?: string;
  note?: string;
};

export type StartState = {
  draft: string;
  attachments: Attachment[];
  model: ModelId;
  mode: ModeId;
  runs: Run[];
  sessions: PastSession[];
  sentCount: number;
  hint: Hint;
  refusals: number;
  spoken: string;
  demoLens: Point | null;
  demoRipples: number;
  isSidebarOpen: boolean;
};

export type StartAction =
  | { type: 'typed'; text: string }
  | { type: 'picked'; prompt: string }
  | { type: 'attached'; attachments: Attachment[] }
  | { type: 'detached'; id: string }
  | { type: 'modelSet'; model: ModelId }
  | { type: 'modeSet'; mode: ModeId }
  | { type: 'sent' }
  | { type: 'runStarted'; id: string }
  | { type: 'runFinished'; id: string }
  | { type: 'decided'; id: string; decision: Decision }
  | { type: 'lens'; point: Point | null }
  | { type: 'rippled' }
  | { type: 'sidebar'; isOpen: boolean };

type Step = SessionStep<StartState, StartAction>;

const MINUTE_MS = 60_000;

const LOADED_AT = Date.now();

function since(minutes: number) {
  const elapsed = minutes * MINUTE_MS;
  return LOADED_AT - elapsed;
}

function endedAtOf(seed: RunSeed) {
  if (seed.endedMinutesAgo === undefined) {
    return undefined;
  }
  return since(seed.endedMinutesAgo);
}

function runOf(seed: RunSeed): Run {
  return {
    id: seed.id,
    agentId: seed.agentId,
    title: seed.title,
    status: seed.status,
    startedAt: since(seed.startedMinutesAgo),
    endedAt: endedAtOf(seed),
    costUsd: seed.costUsd,
    request: seed.request,
    note: seed.failure,
  };
}

export const INITIAL: StartState = {
  draft: '',
  attachments: [],
  model: 'claude-sonnet',
  mode: 'ask',
  runs: RUNS.map(runOf),
  sessions: SESSIONS,
  sentCount: 0,
  hint: 'none',
  refusals: 0,
  spoken: '',
  demoLens: null,
  demoRipples: 0,
  isSidebarOpen: false,
};

export function sentRunIdOf(count: number) {
  return `sent-${count}`;
}

const FIRST_SENT_RUN = sentRunIdOf(1);

function refused(state: StartState, hint: Hint, spoken: string): StartState {
  const refusals = state.refusals + 1;
  return { ...state, hint, refusals, spoken };
}

function attached(state: StartState, added: Attachment[]): StartState {
  const room = MAX_ATTACHMENTS - state.attachments.length;
  const accepted = added.slice(0, room);
  const attachments = [...state.attachments, ...accepted];
  const hasOverflow = added.length > room;
  if (hasOverflow) {
    return refused({ ...state, attachments }, 'full', FULL_HINT);
  }
  return { ...state, attachments, hint: 'none' };
}

function detached(state: StartState, id: string): StartState {
  const attachments = state.attachments.filter((file) => file.id !== id);
  return { ...state, attachments, hint: 'none' };
}

function shortTitleOf(text: string) {
  const words = wordsOf(text);
  const kept = words.slice(0, TITLE_WORDS);
  return kept.join(' ');
}

/** A sent prompt becomes the newest run and the newest session. The list of runs keeps to the latest ones. */
function sent(state: StartState, now: number): StartState {
  const text = state.draft.trim();
  if (text === '') {
    return refused(state, 'empty', EMPTY_PROMPT_HINT);
  }
  const sentCount = state.sentCount + 1;
  const id = sentRunIdOf(sentCount);
  const title = shortTitleOf(text);
  const run: Run = {
    id,
    agentId: STARTING_AGENT,
    title: text,
    status: 'queued',
    startedAt: now,
    costUsd: 0,
  };
  const session: PastSession = { id, day: 'Today', title, prompt: text };
  const runs = [run, ...state.runs];
  const latestRuns = runs.slice(0, RUNS_SHOWN);
  const spoken = `Session started: ${title}`;
  return {
    ...state,
    draft: '',
    attachments: [],
    runs: latestRuns,
    sessions: [session, ...state.sessions],
    sentCount,
    hint: 'none',
    spoken,
  };
}

function patchedRun(
  state: StartState,
  id: string,
  from: RunStatus,
  change: (run: Run) => Run
): StartState {
  const runs = state.runs.map((run) => {
    const isTarget = run.id === id && run.status === from;
    if (!isTarget) {
      return run;
    }
    return change(run);
  });
  return { ...state, runs };
}

/** A run that starts again forgets when it stopped, so its clock counts on from its first start. */
function runStarted(state: StartState, id: string): StartState {
  return patchedRun(state, id, 'queued', (run) => ({
    ...run,
    status: 'running',
    endedAt: undefined,
  }));
}

const DEMO_RUN_USD = 0.094;

function finishedRun(run: Run, now: number): Run {
  const costUsd = run.costUsd + DEMO_RUN_USD;
  return { ...run, status: 'done', endedAt: now, costUsd };
}

function runFinished(state: StartState, id: string, now: number): StartState {
  return patchedRun(state, id, 'running', (run) => finishedRun(run, now));
}

function decided(
  state: StartState,
  id: string,
  decision: Decision,
  now: number
): StartState {
  if (decision === 'approved') {
    const allowed = patchedRun(state, id, 'waiting', (run) => ({
      ...run,
      status: 'queued',
      note: 'Allowed by you',
    }));
    return { ...allowed, spoken: 'Allowed. The run starts again' };
  }
  const stopped = patchedRun(state, id, 'waiting', (run) => ({
    ...run,
    status: 'done',
    endedAt: now,
    note: 'Denied by you, nothing was run',
  }));
  return { ...stopped, spoken: 'Denied. Nothing was run' };
}

function rippled(state: StartState): StartState {
  const demoRipples = state.demoRipples + 1;
  return { ...state, demoRipples };
}

export function applyAt(
  state: StartState,
  action: StartAction,
  now: number
): StartState {
  switch (action.type) {
    case 'typed':
      return { ...state, draft: action.text, hint: 'none' };
    case 'picked':
      return { ...state, draft: action.prompt, hint: 'none' };
    case 'attached':
      return attached(state, action.attachments);
    case 'detached':
      return detached(state, action.id);
    case 'modelSet':
      return { ...state, model: action.model };
    case 'modeSet':
      return { ...state, mode: action.mode };
    case 'sent':
      return sent(state, now);
    case 'runStarted':
      return runStarted(state, action.id);
    case 'runFinished':
      return runFinished(state, action.id, now);
    case 'decided':
      return decided(state, action.id, action.decision, now);
    case 'lens':
      return { ...state, demoLens: action.point };
    case 'rippled':
      return rippled(state);
    case 'sidebar':
      return { ...state, isSidebarOpen: action.isOpen };
  }
}

export function reducer(state: StartState, action: StartAction) {
  return applyAt(state, action, Date.now());
}

function hasSent(state: StartState) {
  return state.sentCount > 0;
}

function hasDecided(state: StartState) {
  const run = state.runs.find((candidate) => candidate.id === WAITING_RUN);
  return run?.status !== 'waiting';
}

